window.RP_SESSION={"id":"S-34807faddcb6","messages":[{"id":"RP-0172370","time":"2026-06-13T01:10:00+09:00","room":"RP","name":"아도니스","profile":"올리브","identity":"reviewed","type":"dialogue","body":"잇-샤. 의뢰를 끝맞췄습니다.","characters":["P-6eeed2b4661f"]},{"id":"RP-0172371","time":"2026-06-13T01:10:00+09:00","room":"RP","name":"아도니스","profile":"올리브","identity":"reviewed","type":"dialogue","body":"이럴 때는 역시 이거죠.","characters":["P-6eeed2b4661f"]},{"id":"RP-0172372","time":"2026-06-13T01:10:00+09:00","room":"RP","name":"아도니스","profile":"올리브","identity":"reviewed","type":"dialogue","body":"이걸... 이렇게 해서","characters":["P-6eeed2b4661f"]},{"id":"RP-0172373","time":"2026-06-13T01:10:00+09:00","room":"RP","name":"아도니스","profile":"올리브","identity":"reviewed","type":"dialogue","body":" 됐다.","characters":["P-6eeed2b4661f"]},{"id":"RP-0172374","time":"2026-06-13T01:10:00+09:00","room":"RP","name":"아도니스","profile":"올리브","identity":"reviewed","type":"dialogue","body":"!모닥불","characters":["P-6eeed2b4661f"]},{"id":"RP-0172375","time":"2026-06-13T01:10:00+09:00","room":"RP","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"모닥불에 불씨가 옮겨 붙습니다.\n따뜻한 온기가 피어오릅니다.\n\n ♩ https://youtu.be/3GNyTB6p6i0?si=4L6Rg34M-gtWRqUj","characters":[]},{"id":"RP-0172376","time":"2026-06-13T01:12:00+09:00","room":"RP","name":"리엔 / 네레이드","profile":"리엔 에이라스","identity":"reviewed","type":"dialogue","body":"꿀렁꿀렁~","characters":["P-a161473e74e0"]},{"id":"RP-0172377","time":"2026-06-13T01:12:00+09:00","room":"RP","name":"아도니스","profile":"올리브","identity":"reviewed","type":"dialogue","body":" 물친구다.","characters":["P-6eeed2b4661f"]},{"id":"RP-0172378","time":"2026-06-13T01:13:00+09:00","room":"RP","name":"리엔 / 네레이드","profile":"리엔 에이라스","identity":"reviewed","type":"dialogue","body":"리엔은 모닥불가에 누워있고 네레이드가 모닥불빛을 받아서 빤짝빤짝 빛나고있어요~\n\n\"아도니스씨. 오늘정말 멋졌어요.\"","characters":["P-a161473e74e0"]},{"id":"RP-0172379","time":"2026-06-13T01:13:00+09:00","room":"RP","name":"리엔 / 네레이드","profile":"리엔 에이라스","identity":"reviewed","type":"dialogue","body":"\"앞으로도 네레이드랑 협동해서 씨앗키우는거 자주해봐요. 효과 좋은거같아요!\"","characters":["P-a161473e74e0"]},{"id":"RP-0172380","time":"2026-06-13T01:14:00+09:00","room":"RP","name":"아도니스","profile":"올리브","identity":"reviewed","type":"dialogue","body":" \"그런가?\"\n\n 뿌듯.","characters":["P-6eeed2b4661f"]},{"id":"RP-0172381","time":"2026-06-13T01:14:00+09:00","room":"RP","name":"아도니스","profile":"올리브","identity":"reviewed","type":"dialogue","body":" \"둘 다 도와줘서 고마워.\"","characters":["P-6eeed2b4661f"]},{"id":"RP-0172382","time":"2026-06-13T01:15:00+09:00","room":"RP","name":"리엔 / 네레이드","profile":"리엔 에이라스","identity":"reviewed","type":"dialogue","body":"\"헤헤, 별걸요. 아도니스씨가 한건걸요.\"\n\n네레이드도 옆에서 쑥스러워하네요~\n\n\"아도니스씨는 정말 좋은사람같아요. 칭찬들으면 우쭐할만도한데 고맙다고부터 하니까요.\"","characters":["P-a161473e74e0"]},{"id":"RP-0172383","time":"2026-06-13T01:16:00+09:00","room":"RP","name":"아도니스","profile":"올리브","identity":"reviewed","type":"dialogue","body":" 헉.","characters":["P-6eeed2b4661f"]},{"id":"RP-0172384","time":"2026-06-13T01:16:00+09:00","room":"RP","name":"아도니스","profile":"올리브","identity":"reviewed","type":"dialogue","body":"부끄럽다.","characters":["P-6eeed2b4661f"]},{"id":"RP-0172385","time":"2026-06-13T01:16:00+09:00","room":"RP","name":"아도니스","profile":"올리브","identity":"reviewed","type":"dialogue","body":"...","characters":["P-6eeed2b4661f"]},{"id":"RP-0172386","time":"2026-06-13T01:17:00+09:00","room":"RP","name":"아도니스","profile":"올리브","identity":"reviewed","type":"dialogue","body":" \"있지... 나 오늘 사람 처음 죽였다?\"\n\n 내 손으로 목 비튼건 아녔지만\n\n \"사람은 허접이더라. 체급에 비해서 급소가 너무 얇고 드러나있어.\"","characters":["P-6eeed2b4661f"]},{"id":"RP-0172387","time":"2026-06-13T01:18:00+09:00","room":"RP","name":"리엔 / 네레이드","profile":"리엔 에이라스","identity":"reviewed","type":"dialogue","body":"리엔이 통나무벤치에서 일어나서 아도니스를 쓰다듬습니다.\n\n\"해보니까 어때요? 아도니스씨의 마음이요.\"","characters":["P-a161473e74e0"]},{"id":"RP-0172388","time":"2026-06-13T01:19:00+09:00","room":"RP","name":"아도니스","profile":"올리브","identity":"reviewed","type":"dialogue","body":" ?","characters":["P-6eeed2b4661f"]},{"id":"RP-0172389","time":"2026-06-13T01:19:00+09:00","room":"RP","name":"아도니스","profile":"올리브","identity":"reviewed","type":"dialogue","body":" \"문제가 될까?\"","characters":["P-6eeed2b4661f"]},{"id":"RP-0172390","time":"2026-06-13T01:20:00+09:00","room":"RP","name":"아도니스","profile":"올리브","identity":"reviewed","type":"dialogue","body":" \"사람들은 모든 생이 귀중하다면서 사람 죽는거에 특히 예민 반응을 해.\"","characters":["P-6eeed2b4661f"]},{"id":"RP-0172391","time":"2026-06-13T01:21:00+09:00","room":"RP","name":"아도니스","profile":"올리브","identity":"reviewed","type":"dialogue","body":" 저들이 가장 특별한것처럼","characters":["P-6eeed2b4661f"]},{"id":"RP-0172392","time":"2026-06-13T01:21:00+09:00","room":"RP","name":"리엔 / 네레이드","profile":"리엔 에이라스","identity":"reviewed","type":"dialogue","body":"\"아도니스씨는 그렇군요. 다행이에요.\"","characters":["P-a161473e74e0"]},{"id":"RP-0172393","time":"2026-06-13T01:21:00+09:00","room":"RP","name":"아도니스","profile":"올리브","identity":"reviewed","type":"dialogue","body":"갸웃.","characters":["P-6eeed2b4661f"]},{"id":"RP-0172394","time":"2026-06-13T01:21:00+09:00","room":"RP","name":"아도니스","profile":"올리브","identity":"reviewed","type":"dialogue","body":" \"나 머리 장식 사고 싶어.\"","characters":["P-6eeed2b4661f"]},{"id":"RP-0172395","time":"2026-06-13T01:22:00+09:00","room":"RP","name":"아도니스","profile":"올리브","identity":"reviewed","type":"dialogue","body":"돈 받았으니까","characters":["P-6eeed2b4661f"]},{"id":"RP-0172396","time":"2026-06-13T01:22:00+09:00","room":"RP","name":"아도니스","profile":"올리브","identity":"reviewed","type":"dialogue","body":"여기 온 뒤로 나름 자아가 생겨 갖고싶은 것도 생기게 된 아도니스였다.","characters":["P-6eeed2b4661f"]},{"id":"RP-0172397","time":"2026-06-13T01:22:00+09:00","room":"RP","name":"리엔 / 네레이드","profile":"리엔 에이라스","identity":"reviewed","type":"dialogue","body":"\"오늘 활약하셨으니까 제가 사드릴게요. 어떤걸로 사드릴까요? 나비모양도 잘어울릴거갇고.\"\n\n머리를 쓰다듬어보며 상상해봅니다.","characters":["P-a161473e74e0"]},{"id":"RP-0172398","time":"2026-06-13T01:23:00+09:00","room":"RP","name":"아도니스","profile":"올리브","identity":"reviewed","type":"dialogue","body":" 어김없이 맞쓰담을 한다.\n\n \"직접 보고 고를래.\"","characters":["P-6eeed2b4661f"]},{"id":"RP-0172399","time":"2026-06-13T01:24:00+09:00","room":"RP","name":"리엔 / 네레이드","profile":"리엔 에이라스","identity":"reviewed","type":"dialogue","body":"\"좋아요, 같이 시장에갈까요?\"","characters":["P-a161473e74e0"]},{"id":"RP-0172400","time":"2026-06-13T01:24:00+09:00","room":"RP","name":"아도니스","profile":"올리브","identity":"reviewed","type":"dialogue","body":"끄덕끄덕쓴.","characters":["P-6eeed2b4661f"]},{"id":"RP-0172401","time":"2026-06-13T01:25:00+09:00","room":"RP","name":"리엔 / 네레이드","profile":"리엔 에이라스","identity":"reviewed","type":"dialogue","body":"\"좋아요~\"\n\n아도니스와함께 시장으로 갑시다~","characters":["P-a161473e74e0"]},{"id":"RP-0172402","time":"2026-06-13T01:25:00+09:00","room":"RP","name":"아도니스","profile":"올리브","identity":"reviewed","type":"dialogue","body":" 챱챱챱챱챱.","characters":["P-6eeed2b4661f"]},{"id":"RP-0172403","time":"2026-06-13T01:25:00+09:00","room":"RP","name":"아도니스","profile":"올리브","identity":"reviewed","type":"dialogue","body":" \"근데 나 어떻게 쓰는지는 몰라.\"\n\n 리엔은 알아?","characters":["P-6eeed2b4661f"]},{"id":"RP-0172404","time":"2026-06-13T01:27:00+09:00","room":"RP","name":"아도니스","profile":"올리브","identity":"reviewed","type":"dialogue","body":"머리장식 말하는 겁니다.","characters":["P-6eeed2b4661f"]},{"id":"RP-0172405","time":"2026-06-13T01:28:00+09:00","room":"RP","name":"리엔 / 네레이드","profile":"리엔 에이라스","identity":"reviewed","type":"dialogue","body":"\"제가 가르쳐드릴게요.\"\n\n시장에서 머리장식을 파는곳에옵니다. 머리띠부터, 핀형태 같은것들도!\n\n\"디자인부터 골라볼까요?\"","characters":["P-a161473e74e0"]},{"id":"RP-0172406","time":"2026-06-13T01:30:00+09:00","room":"RP","name":"아도니스","profile":"올리브","identity":"reviewed","type":"dialogue","body":" 챱챱챱","characters":["P-6eeed2b4661f"]},{"id":"RP-0172407","time":"2026-06-13T01:30:00+09:00","room":"RP","name":"아도니스","profile":"올리브","identity":"reviewed","type":"dialogue","body":" \"무슨 색이 어울릴까.\"\n\n 노랗고 희고 검고 길쭉한 놈.","characters":["P-6eeed2b4661f"]},{"id":"RP-0172408","time":"2026-06-13T01:32:00+09:00","room":"RP","name":"아도니스","profile":"올리브","identity":"reviewed","type":"dialogue","body":"움.","characters":["P-6eeed2b4661f"]},{"id":"RP-0172409","time":"2026-06-13T01:32:00+09:00","room":"RP","name":"아도니스","profile":"올리브","identity":"reviewed","type":"dialogue","body":"흠,","characters":["P-6eeed2b4661f"]},{"id":"RP-0172410","time":"2026-06-13T01:32:00+09:00","room":"RP","name":"리엔 / 네레이드","profile":"리엔 에이라스","identity":"reviewed","type":"dialogue","body":"\"노란머리에...\"","characters":["P-a161473e74e0"]},{"id":"RP-0172411","time":"2026-06-13T01:33:00+09:00","room":"RP","name":"리엔 / 네레이드","profile":"리엔 에이라스","identity":"reviewed","type":"dialogue","body":"\"보색으로 보라색이나 남색은어때요?\"","characters":["P-a161473e74e0"]},{"id":"RP-0172412","time":"2026-06-13T01:33:00+09:00","room":"RP","name":"아도니스","profile":"올리브","identity":"reviewed","type":"dialogue","body":"밀색 느낌의 금발!","characters":["P-6eeed2b4661f"]},{"id":"RP-0172413","time":"2026-06-13T01:33:00+09:00","room":"RP","name":"아도니스","profile":"올리브","identity":"reviewed","type":"dialogue","body":" 생각치도 못했다.","characters":["P-6eeed2b4661f"]},{"id":"RP-0172414","time":"2026-06-13T01:33:00+09:00","room":"RP","name":"아도니스","profile":"올리브","identity":"reviewed","type":"dialogue","body":" \"음...\"","characters":["P-6eeed2b4661f"]},{"id":"RP-0172415","time":"2026-06-13T01:34:00+09:00","room":"RP","name":"아도니스","profile":"올리브","identity":"reviewed","type":"dialogue","body":"보랗고 파란계열은 비싸고 드물긴 하지만, 두툼한 리본과 깃털모양이 있었다.","characters":["P-6eeed2b4661f"]},{"id":"RP-0172416","time":"2026-06-13T01:35:00+09:00","room":"RP","name":"아도니스","profile":"올리브","identity":"reviewed","type":"dialogue","body":" \"깃털 모양이 궁금해.\"\n\n 파란 색소 찌일끔 들어간거","characters":["P-6eeed2b4661f"]},{"id":"RP-0172417","time":"2026-06-13T01:35:00+09:00","room":"RP","name":"리엔 / 네레이드","profile":"리엔 에이라스","identity":"reviewed","type":"dialogue","body":"\"깃털모양, 이거이쁘네요!\"\n\n가게주인에게 허락을받고 아도니스에게 시착시켜봅니다.","characters":["P-a161473e74e0"]},{"id":"RP-0172418","time":"2026-06-13T01:38:00+09:00","room":"RP","name":"아도니스","profile":"올리브","identity":"reviewed","type":"dialogue","body":"가게의 물대야 들여다보더니","characters":["P-6eeed2b4661f"]},{"id":"RP-0172419","time":"2026-06-13T01:38:00+09:00","room":"RP","name":"아도니스","profile":"올리브","identity":"reviewed","type":"dialogue","body":"흠... 음...","characters":["P-6eeed2b4661f"]},{"id":"RP-0172420","time":"2026-06-13T01:38:00+09:00","room":"RP","name":"아도니스","profile":"올리브","identity":"reviewed","type":"dialogue","body":" \"파란 깃털은 별로야. 흰색이나 회색이었으면 괜찮았을거 같지만.\"","characters":["P-6eeed2b4661f"]},{"id":"RP-0172421","time":"2026-06-13T01:39:00+09:00","room":"RP","name":"리엔 / 네레이드","profile":"리엔 에이라스","identity":"reviewed","type":"dialogue","body":"\"좋아요, 다른것들도 찾아볼까요?\"\n\n풀어서 제자리에두고, 다른걸 찾아봐요.","characters":["P-a161473e74e0"]},{"id":"RP-0172422","time":"2026-06-13T01:39:00+09:00","room":"RP","name":"아도니스","profile":"올리브","identity":"reviewed","type":"dialogue","body":"흠... 내가 좋아하는 것은 뭘까? 쉽게 풀리지 않습니다.","characters":["P-6eeed2b4661f"]},{"id":"RP-0172423","time":"2026-06-13T01:39:00+09:00","room":"RP","name":"리엔 / 네레이드","profile":"리엔 에이라스","identity":"reviewed","type":"dialogue","body":"예쁜거뭐 없나?","characters":["P-a161473e74e0"]},{"id":"RP-0172424","time":"2026-06-13T01:40:00+09:00","room":"RP","name":"아도니스","profile":"올리브","identity":"reviewed","type":"dialogue","body":"리엔의 추천은 과연...!","characters":["P-6eeed2b4661f"]},{"id":"RP-0172425","time":"2026-06-13T01:42:00+09:00","room":"RP","name":"리엔 / 네레이드","profile":"리엔 에이라스","identity":"reviewed","type":"dialogue","body":"\"이런건 어때요?\"\n\n하얀색 꽃모양 머리핀~","characters":["P-a161473e74e0"]},{"id":"RP-0172426","time":"2026-06-13T01:43:00+09:00","room":"RP","name":"아도니스","profile":"올리브","identity":"reviewed","type":"dialogue","body":" 헉.","characters":["P-6eeed2b4661f"]},{"id":"RP-0172427","time":"2026-06-13T01:43:00+09:00","room":"RP","name":"아도니스","profile":"올리브","identity":"reviewed","type":"dialogue","body":" \"마음에 들어.\"\n\n 볼 붉히기.","characters":["P-6eeed2b4661f"]},{"id":"RP-0172428","time":"2026-06-13T01:44:00+09:00","room":"RP","name":"아도니스","profile":"올리브","identity":"reviewed","type":"dialogue","body":" 나 이런거 좋아하는구나","characters":["P-6eeed2b4661f"]},{"id":"RP-0172429","time":"2026-06-13T01:44:00+09:00","room":"RP","name":"리엔 / 네레이드","profile":"리엔 에이라스","identity":"reviewed","type":"dialogue","body":"머리핀을 꽂아줍니다.\n\n\"자, 이렇게~ 봐요, 예쁘죠?\"","characters":["P-a161473e74e0"]},{"id":"RP-0172430","time":"2026-06-13T01:45:00+09:00","room":"RP","name":"아도니스","profile":"올리브","identity":"reviewed","type":"dialogue","body":"\"웅.\"","characters":["P-6eeed2b4661f"]},{"id":"RP-0172431","time":"2026-06-13T01:45:00+09:00","room":"RP","name":"아도니스","profile":"올리브","identity":"reviewed","type":"dialogue","body":" 장미 모양이랑 아네모네 모양이랑 고민 중입니다.","characters":["P-6eeed2b4661f"]},{"id":"RP-0172432","time":"2026-06-13T01:45:00+09:00","room":"RP","name":"아도니스","profile":"올리브","identity":"reviewed","type":"dialogue","body":" \"리엔은 어느게 더 좋아?\"","characters":["P-6eeed2b4661f"]},{"id":"RP-0172433","time":"2026-06-13T01:45:00+09:00","room":"RP","name":"아도니스","profile":"올리브","identity":"reviewed","type":"dialogue","body":"장미는 흰꽃잎만 겹겹이 쌓여 화려하고","characters":["P-6eeed2b4661f"]},{"id":"RP-0172434","time":"2026-06-13T01:46:00+09:00","room":"RP","name":"아도니스","profile":"올리브","identity":"reviewed","type":"dialogue","body":"아네모네 장수는 상대적으로 적지만 중심부에 암술수술대가 있어 포인트가 있습니다.","characters":["P-6eeed2b4661f"]},{"id":"RP-0172435","time":"2026-06-13T01:46:00+09:00","room":"RP","name":"리엔 / 네레이드","profile":"리엔 에이라스","identity":"reviewed","type":"dialogue","body":"\"저는 장미꽃모양이 아도니스씨한테 더 잘어울린다고 생각해요. 아니면 둘다사서 우리가 각각 같은자리에 끼고다닐까요?\"","characters":["P-a161473e74e0"]},{"id":"RP-0172436","time":"2026-06-13T01:47:00+09:00","room":"RP","name":"아도니스","profile":"올리브","identity":"reviewed","type":"dialogue","body":" \"그건 힘들거 같아.\"","characters":["P-6eeed2b4661f"]},{"id":"RP-0172437","time":"2026-06-13T01:48:00+09:00","room":"RP","name":"리엔 / 네레이드","profile":"리엔 에이라스","identity":"reviewed","type":"dialogue","body":"\"넹...\"","characters":["P-a161473e74e0"]},{"id":"RP-0172438","time":"2026-06-13T01:48:00+09:00","room":"RP","name":"아도니스","profile":"올리브","identity":"reviewed","type":"dialogue","body":"  \"우린 머리 길이 차이가 많이나서 비슷한 머리모양 어려우니까 같은 자리를 만들 수 없어...\"\n\n 이런 이유.","characters":["P-6eeed2b4661f"]},{"id":"RP-0172439","time":"2026-06-13T01:48:00+09:00","room":"RP","name":"아도니스","profile":"올리브","identity":"reviewed","type":"dialogue","body":"흠.","characters":["P-6eeed2b4661f"]},{"id":"RP-0172440","time":"2026-06-13T01:49:00+09:00","room":"RP","name":"리엔 / 네레이드","profile":"리엔 에이라스","identity":"reviewed","type":"dialogue","body":"\"그러면 똑같은걸로 두개사서 각각 어울리는자리에 끼고다니는건 어때요?\"","characters":["P-a161473e74e0"]},{"id":"RP-0172441","time":"2026-06-13T01:49:00+09:00","room":"RP","name":"아도니스","profile":"올리브","identity":"reviewed","type":"dialogue","body":" \"그건 좋아.\"","characters":["P-6eeed2b4661f"]},{"id":"RP-0172442","time":"2026-06-13T01:49:00+09:00","room":"RP","name":"아도니스","profile":"올리브","identity":"reviewed","type":"dialogue","body":" \"음...\"","characters":["P-6eeed2b4661f"]},{"id":"RP-0172443","time":"2026-06-13T01:50:00+09:00","room":"RP","name":"아도니스","profile":"올리브","identity":"reviewed","type":"dialogue","body":" \"이건 내가 사줄게.\"\n\n 꽃송이 장식이 여럿 있는 머리꽂이다.","characters":["P-6eeed2b4661f"]},{"id":"RP-0172444","time":"2026-06-13T01:51:00+09:00","room":"RP","name":"리엔 / 네레이드","profile":"리엔 에이라스","identity":"reviewed","type":"dialogue","body":"\"어머, 고마워요.\"\n\n서로의 머리장식을 사줍니다. 그리고 꽂아보네요.","characters":["P-a161473e74e0"]},{"id":"RP-0172445","time":"2026-06-13T01:51:00+09:00","room":"RP","name":"리엔 / 네레이드","profile":"리엔 에이라스","identity":"reviewed","type":"dialogue","body":"\"어때요, 매력적인가요?\"\n\n아도니스에게 웃어보입니다!","characters":["P-a161473e74e0"]},{"id":"RP-0172446","time":"2026-06-13T01:52:00+09:00","room":"RP","name":"아도니스","profile":"올리브","identity":"reviewed","type":"dialogue","body":"\"멋지네.\"\n\n 후후. 같은 머리 장식이 두당 하나씩 두개지요~.","characters":["P-6eeed2b4661f"]},{"id":"RP-0172447","time":"2026-06-13T01:52:00+09:00","room":"RP","name":"아도니스","profile":"올리브","identity":"reviewed","type":"dialogue","body":" 아도니스도 머리 모양을 고쳐봅니다.","characters":["P-6eeed2b4661f"]},{"id":"RP-0172448","time":"2026-06-13T01:52:00+09:00","room":"RP","name":"아도니스","profile":"올리브","identity":"reviewed","type":"dialogue","body":"...","characters":["P-6eeed2b4661f"]},{"id":"RP-0172449","time":"2026-06-13T01:52:00+09:00","room":"RP","name":"아도니스","profile":"올리브","identity":"reviewed","type":"dialogue","body":"되게 길어서 한참 걸리네요.","characters":["P-6eeed2b4661f"]},{"id":"RP-0172450","time":"2026-06-13T01:53:00+09:00","room":"RP","name":"리엔 / 네레이드","profile":"리엔 에이라스","identity":"reviewed","type":"dialogue","body":"\"아도니스씨도 멋져요. 정말 아름답네요.\"\n\n흐뭇하게 감상중이에요!","characters":["P-a161473e74e0"]},{"id":"RP-0172451","time":"2026-06-13T01:53:00+09:00","room":"RP","name":"아도니스","profile":"올리브","identity":"reviewed","type":"dialogue","body":" \"고마워.\"\n\n 뿌듯.","characters":["P-6eeed2b4661f"]},{"id":"RP-0172452","time":"2026-06-13T01:54:00+09:00","room":"RP","name":"아도니스","profile":"올리브","identity":"reviewed","type":"dialogue","body":"뭔가 머리가 조금 화려해졌다.","characters":["P-6eeed2b4661f"]},{"id":"RP-0172453","time":"2026-06-13T01:55:00+09:00","room":"RP","name":"리엔 / 네레이드","profile":"리엔 에이라스","identity":"reviewed","type":"dialogue","body":"장식이 망가지지않게 쓰담쓰담","characters":["P-a161473e74e0"]},{"id":"RP-0172454","time":"2026-06-13T01:55:00+09:00","room":"RP","name":"아도니스","profile":"올리브","identity":"reviewed","type":"dialogue","body":"아도니스도 맞쓰담","characters":["P-6eeed2b4661f"]},{"id":"RP-0172455","time":"2026-06-13T01:55:00+09:00","room":"RP","name":"아도니스","profile":"올리브","identity":"reviewed","type":"dialogue","body":"이상한 풍경이겠구만.","characters":["P-6eeed2b4661f"]},{"id":"RP-0172456","time":"2026-06-13T01:56:00+09:00","room":"RP","name":"리엔 / 네레이드","profile":"리엔 에이라스","identity":"reviewed","type":"dialogue","body":"\"시장구경좀 더하다갈까요?\"","characters":["P-a161473e74e0"]},{"id":"RP-0172457","time":"2026-06-13T01:57:00+09:00","room":"RP","name":"아도니스","profile":"올리브","identity":"reviewed","type":"dialogue","body":"후음...","characters":["P-6eeed2b4661f"]},{"id":"RP-0172458","time":"2026-06-13T01:57:00+09:00","room":"RP","name":"아도니스","profile":"올리브","identity":"reviewed","type":"dialogue","body":"\"좋아.\"","characters":["P-6eeed2b4661f"]},{"id":"RP-0172459","time":"2026-06-13T01:58:00+09:00","room":"RP","name":"리엔 / 네레이드","profile":"리엔 에이라스","identity":"reviewed","type":"dialogue","body":"\"봐요, 여기서는 예쁜 목각인형들을 팔고있네요!\"\n\n나무로만든 인형들이있는 가게를 가리키며 말해요.","characters":["P-a161473e74e0"]},{"id":"RP-0172460","time":"2026-06-13T01:59:00+09:00","room":"RP","name":"아도니스","profile":"올리브","identity":"reviewed","type":"dialogue","body":"목각인형.","characters":["P-6eeed2b4661f"]},{"id":"RP-0172461","time":"2026-06-13T02:00:00+09:00","room":"RP","name":"리엔 / 네레이드","profile":"리엔 에이라스","identity":"reviewed","type":"dialogue","body":"\"이거귀엽네요.\"\n\n나무로깎은 토끼인형!","characters":["P-a161473e74e0"]},{"id":"RP-0172462","time":"2026-06-13T02:00:00+09:00","room":"RP","name":"아도니스","profile":"올리브","identity":"reviewed","type":"dialogue","body":" \"귀엽다.\"","characters":["P-6eeed2b4661f"]},{"id":"RP-0172463","time":"2026-06-13T02:00:00+09:00","room":"RP","name":"리엔 / 네레이드","profile":"리엔 에이라스","identity":"reviewed","type":"dialogue","body":"족발! 족발!","characters":["P-a161473e74e0"]},{"id":"RP-0172464","time":"2026-06-13T02:01:00+09:00","room":"RP","name":"아도니스","profile":"올리브","identity":"reviewed","type":"dialogue","body":" \"저건 어때?\"\n\n 옆 가게의 푹신해보이는 돌고래.\n\n \"저거 처음보는 동물이야. 바다사나?\"","characters":["P-6eeed2b4661f"]},{"id":"RP-0172465","time":"2026-06-13T02:01:00+09:00","room":"RP","name":"리엔 / 네레이드","profile":"리엔 에이라스","identity":"reviewed","type":"dialogue","body":"\"네, 바다에서는 자주보이는 동물인데, 돌고래라고 해요. 오케아노스랑 바다에가서 놀적에는 자주 보였었죠.\"","characters":["P-a161473e74e0"]},{"id":"RP-0172466","time":"2026-06-13T02:02:00+09:00","room":"RP","name":"리엔 / 네레이드","profile":"리엔 에이라스","identity":"reviewed","type":"dialogue","body":"\"머리위에 숨구멍이 있는데, 거기로 숨을쉬어요. 귀여운 녀석들이죠!\"","characters":["P-a161473e74e0"]},{"id":"RP-0172467","time":"2026-06-13T02:02:00+09:00","room":"RP","name":"아도니스","profile":"올리브","identity":"reviewed","type":"dialogue","body":" \"신기한 친구네.\"\n\n 귀엽다.","characters":["P-6eeed2b4661f"]},{"id":"RP-0172468","time":"2026-06-13T02:02:00+09:00","room":"RP","name":"아도니스","profile":"올리브","identity":"reviewed","type":"dialogue","body":" \"난 바다 친구들이 좋더라.\"","characters":["P-6eeed2b4661f"]},{"id":"RP-0172469","time":"2026-06-13T02:02:00+09:00","room":"RP","name":"리엔 / 네레이드","profile":"리엔 에이라스","identity":"reviewed","type":"dialogue","body":"\"여기 람제이대공 닮은녀석도 있네요!\"\n\n다람쥐 목각인형!","characters":["P-a161473e74e0"]},{"id":"RP-0172470","time":"2026-06-13T02:03:00+09:00","room":"RP","name":"리엔 / 네레이드","profile":"리엔 에이라스","identity":"reviewed","type":"dialogue","body":"\"바다에는 무서운것들도 많지만, 신비롭고 아름다운것도 그만큼 많이있죠!\"","characters":["P-a161473e74e0"]},{"id":"RP-0172471","time":"2026-06-13T02:03:00+09:00","room":"RP","name":"리엔 / 네레이드","profile":"리엔 에이라스","identity":"reviewed","type":"dialogue","body":"\"나중에같이 우리고향 가봐요~\"","characters":["P-a161473e74e0"]},{"id":"RP-0172472","time":"2026-06-13T02:03:00+09:00","room":"RP","name":"아도니스","profile":"올리브","identity":"reviewed","type":"dialogue","body":" \"아냐. 람-제이 공은 눈매가 좀 더 날카로워.\"","characters":["P-6eeed2b4661f"]},{"id":"RP-0172473","time":"2026-06-13T02:03:00+09:00","room":"RP","name":"리엔 / 네레이드","profile":"리엔 에이라스","identity":"reviewed","type":"dialogue","body":"\"그런 디테일한 차이도... 역시 친구군요!\"","characters":["P-a161473e74e0"]},{"id":"RP-0172474","time":"2026-06-13T02:04:00+09:00","room":"RP","name":"리엔 / 네레이드","profile":"리엔 에이라스","identity":"reviewed","type":"dialogue","body":"그리고 어디선가 고소한향기가 풍겨옵니다. 메뚜기를 볶고있네요!\n\n\"아도니스씨도 메뚜기볶음 좋아해요?\"","characters":["P-a161473e74e0"]},{"id":"RP-0172475","time":"2026-06-13T02:04:00+09:00","room":"RP","name":"아도니스","profile":"올리브","identity":"reviewed","type":"dialogue","body":" \"그리고 람-제이 공은 잘생긴 다람쥐야.\"","characters":["P-6eeed2b4661f"]},{"id":"RP-0172476","time":"2026-06-13T02:04:00+09:00","room":"RP","name":"아도니스","profile":"올리브","identity":"reviewed","type":"dialogue","body":"오.","characters":["P-6eeed2b4661f"]},{"id":"RP-0172477","time":"2026-06-13T02:04:00+09:00","room":"RP","name":"아도니스","profile":"올리브","identity":"reviewed","type":"dialogue","body":"\"나 메뚜기 먹는거 좋아.\"","characters":["P-6eeed2b4661f"]},{"id":"RP-0172478","time":"2026-06-13T02:05:00+09:00","room":"RP","name":"리엔 / 네레이드","profile":"리엔 에이라스","identity":"reviewed","type":"dialogue","body":"\"좋아요~\"\n\n메뚜기한봉지를 사와서 아도니스입에 쏙~넣어줍니다.","characters":["P-a161473e74e0"]},{"id":"RP-0172479","time":"2026-06-13T02:05:00+09:00","room":"RP","name":"아도니스","profile":"올리브","identity":"reviewed","type":"dialogue","body":"오돗오돗 씹히는 맛이 좋아 먹기 좋군요.","characters":["P-6eeed2b4661f"]},{"id":"RP-0172480","time":"2026-06-13T02:06:00+09:00","room":"RP","name":"리엔 / 네레이드","profile":"리엔 에이라스","identity":"reviewed","type":"dialogue","body":"리엔도 아작아작 씹어먹으며 기분좋게 웃고있읍니다~","characters":["P-a161473e74e0"]},{"id":"RP-0172481","time":"2026-06-13T02:07:00+09:00","room":"RP","name":"리엔 / 네레이드","profile":"리엔 에이라스","identity":"reviewed","type":"dialogue","body":"\"아도니스씨는 정말 신비로워요, 좋은의미로요.\"","characters":["P-a161473e74e0"]},{"id":"RP-0172482","time":"2026-06-13T02:08:00+09:00","room":"RP","name":"아도니스","profile":"올리브","identity":"reviewed","type":"dialogue","body":" \"신비롭다는 게 뭐야\"\n\n 갸웃.","characters":["P-6eeed2b4661f"]},{"id":"RP-0172483","time":"2026-06-13T02:08:00+09:00","room":"RP","name":"리엔 / 네레이드","profile":"리엔 에이라스","identity":"reviewed","type":"dialogue","body":"\"말도 많지않고, 드루이드기도하고, 가끔씩 이해하기힘든 행동을 하기도하고.\"","characters":["P-a161473e74e0"]},{"id":"RP-0172484","time":"2026-06-13T02:08:00+09:00","room":"RP","name":"리엔 / 네레이드","profile":"리엔 에이라스","identity":"reviewed","type":"dialogue","body":"\"하지만 그런 아도니스씨라서 좋은걸지도 모르겠어요.\"","characters":["P-a161473e74e0"]},{"id":"RP-0172485","time":"2026-06-13T02:09:00+09:00","room":"RP","name":"아도니스","profile":"올리브","identity":"reviewed","type":"dialogue","body":"흐음.","characters":["P-6eeed2b4661f"]},{"id":"RP-0172486","time":"2026-06-13T02:09:00+09:00","room":"RP","name":"아도니스","profile":"올리브","identity":"reviewed","type":"dialogue","body":"사랑받기를 바라는 것은, 아도니스에겐 분명한 죄겠지.","characters":["P-6eeed2b4661f"]},{"id":"RP-0172487","time":"2026-06-13T02:09:00+09:00","room":"RP","name":"아도니스","profile":"올리브","identity":"reviewed","type":"dialogue","body":"라고도 생각했다.","characters":["P-6eeed2b4661f"]},{"id":"RP-0172488","time":"2026-06-13T02:09:00+09:00","room":"RP","name":"아도니스","profile":"올리브","identity":"reviewed","type":"dialogue","body":" 근데 세상은 내게 언제나 희망을 주는구나.","characters":["P-6eeed2b4661f"]},{"id":"RP-0172489","time":"2026-06-13T02:10:00+09:00","room":"RP","name":"아도니스","profile":"올리브","identity":"reviewed","type":"dialogue","body":" \"나 좋아해줘서 고마워. 나도 상냥한 사람인 리엔이 좋아.\"","characters":["P-6eeed2b4661f"]},{"id":"RP-0172490","time":"2026-06-13T02:10:00+09:00","room":"RP","name":"아도니스","profile":"올리브","identity":"reviewed","type":"dialogue","body":"그리고 역시 돌고래 갖고 싶어.","characters":["P-6eeed2b4661f"]},{"id":"RP-0172491","time":"2026-06-13T02:10:00+09:00","room":"RP","name":"리엔 / 네레이드","profile":"리엔 에이라스","identity":"reviewed","type":"dialogue","body":"리엔은 생글생글 웃으면서 어찌알았는지 돌고래인형도 사줍니다.","characters":["P-a161473e74e0"]},{"id":"RP-0172492","time":"2026-06-13T02:10:00+09:00","room":"RP","name":"리엔 / 네레이드","profile":"리엔 에이라스","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-a161473e74e0"]},{"id":"RP-0172493","time":"2026-06-13T02:10:00+09:00","room":"RP","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"...good for you.","characters":[]}]};
